"""Tokenizer, AST, and recursive-descent parser for minisql.

The parser deliberately keeps the source offsets of every expression so the
engine can use the expression's original text as a default output name.
"""

import re
from dataclasses import dataclass, field
from typing import List, Optional, Sequence, Tuple

from .errors import QueryError


# ---------------------------------------------------------------------------
# Tokens


KEYWORDS = {
    "SELECT",
    "DISTINCT",
    "FROM",
    "WHERE",
    "GROUP",
    "BY",
    "HAVING",
    "ORDER",
    "LIMIT",
    "OFFSET",
    "AS",
    "ASC",
    "DESC",
    "AND",
    "OR",
    "NOT",
    "NULL",
    "TRUE",
    "FALSE",
    "IS",
    "IN",
    "BETWEEN",
    "LIKE",
}

_TWO_CHAR_OPS = ("<=", ">=", "<>", "!=", "||")
_ONE_CHAR_OPS = set("=<>+-*/(),;.")


@dataclass
class Token:
    kind: str
    value: object
    text: str
    start: int
    end: int


def _is_name_start(ch: str) -> bool:
    return ch == "_" or ch.isalpha()


def _is_name_part(ch: str) -> bool:
    return ch == "_" or ch.isalnum()


def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def tokenize(sql: str) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    n = len(sql)

    while i < n:
        ch = sql[i]

        if ch.isspace():
            i += 1
            continue

        if ch == "'":
            start = i
            i += 1
            out = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        out.append("'")
                        i += 2
                        continue
                    i += 1
                    break
                out.append(sql[i])
                i += 1
            else:
                raise QueryError(
                    "syntax error: unterminated string literal at position %d" % start
                )
            tokens.append(Token("string", "".join(out), sql[start:i], start, i))
            continue

        if ch == '"':
            start = i
            i += 1
            out = []
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        out.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                out.append(sql[i])
                i += 1
            else:
                raise QueryError(
                    "syntax error: unterminated quoted name at position %d" % start
                )
            tokens.append(Token("qname", "".join(out), sql[start:i], start, i))
            continue

        if _is_digit(ch) or (ch == "." and i + 1 < n and _is_digit(sql[i + 1])):
            start = i
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            text = sql[start:i]
            value = float(text) if is_float else int(text)
            tokens.append(Token("number", value, text, start, i))
            continue

        if _is_name_start(ch):
            start = i
            i += 1
            while i < n and _is_name_part(sql[i]):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token("kw", upper, word, start, i))
            else:
                tokens.append(Token("name", word, word, start, i))
            continue

        two = sql[i : i + 2]
        if two in _TWO_CHAR_OPS:
            tokens.append(Token("op", two, two, i, i + 2))
            i += 2
            continue

        if ch in _ONE_CHAR_OPS:
            tokens.append(Token("op", ch, ch, i, i + 1))
            i += 1
            continue

        raise QueryError(
            "syntax error: unexpected character %r at position %d" % (ch, i)
        )

    tokens.append(Token("eof", None, "", n, n))
    return tokens


# ---------------------------------------------------------------------------
# AST


@dataclass
class Expr:
    start: int
    end: int


@dataclass
class Literal(Expr):
    value: object


@dataclass
class Column(Expr):
    name: str
    quoted: bool = False
    index: Optional[int] = None


@dataclass
class Paren(Expr):
    operand: Expr


@dataclass
class Unary(Expr):
    op: str
    operand: Expr


@dataclass
class Binary(Expr):
    op: str
    left: Expr
    right: Expr


@dataclass
class IsNull(Expr):
    operand: Expr
    negated: bool = False


@dataclass
class InList(Expr):
    operand: Expr
    items: List[Expr] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negated: bool = False


@dataclass
class Like(Expr):
    operand: Expr
    pattern: Expr
    negated: bool = False


@dataclass
class Call(Expr):
    name: str
    args: List[Expr] = field(default_factory=list)
    star: bool = False
    is_aggregate: bool = False


@dataclass
class OutputRef(Expr):
    """An ORDER BY reference to a column of the result."""

    index: int = 0


@dataclass
class SelectItem:
    expr: Optional[Expr]
    alias: Optional[str] = None
    star: bool = False


@dataclass
class OrderItem:
    expr: Expr
    descending: bool = False


@dataclass
class Query:
    sql: str
    distinct: bool
    items: List[SelectItem]
    table: str
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


# ---------------------------------------------------------------------------
# Structural comparison (used to recognize GROUP BY expressions)


def expr_key(node: Expr):
    """Return a hashable representation of an expression's structure.

    Parentheses are ignored, and columns are compared by their bound index.
    """
    if isinstance(node, Paren):
        return expr_key(node.operand)
    if isinstance(node, Literal):
        value = node.value
        if value is None:
            return ("lit", "null")
        if isinstance(value, bool):
            return ("lit", "bool", value)
        if isinstance(value, (int, float)):
            return ("lit", "num", value)
        if isinstance(value, str):
            return ("lit", "str", value)
        return ("lit", repr(value))
    if isinstance(node, Column):
        if node.index is not None:
            return ("col", node.index)
        return ("colname", node.name.casefold())
    if isinstance(node, Unary):
        return ("unary", node.op, expr_key(node.operand))
    if isinstance(node, Binary):
        return ("binary", node.op, expr_key(node.left), expr_key(node.right))
    if isinstance(node, IsNull):
        return ("isnull", node.negated, expr_key(node.operand))
    if isinstance(node, InList):
        return (
            "in",
            node.negated,
            expr_key(node.operand),
            tuple(expr_key(item) for item in node.items),
        )
    if isinstance(node, Between):
        return (
            "between",
            node.negated,
            expr_key(node.operand),
            expr_key(node.low),
            expr_key(node.high),
        )
    if isinstance(node, Like):
        return (
            "like",
            node.negated,
            expr_key(node.operand),
            expr_key(node.pattern),
        )
    if isinstance(node, Call):
        return (
            "call",
            node.name.casefold(),
            node.star,
            tuple(expr_key(arg) for arg in node.args),
        )
    if isinstance(node, OutputRef):
        return ("output", node.index)
    return ("unknown", id(node))


# ---------------------------------------------------------------------------
# Parser


_COMPARISON_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers ------------------------------------------------------

    def peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def at_kw(self, keyword: str) -> bool:
        tok = self.peek()
        return tok.kind == "kw" and tok.value == keyword

    def match_kw(self, keyword: str) -> bool:
        if self.at_kw(keyword):
            self.advance()
            return True
        return False

    def expect_kw(self, keyword: str) -> Token:
        if not self.at_kw(keyword):
            self.error("expected %s" % keyword)
        return self.advance()

    def at_op(self, op: str) -> bool:
        tok = self.peek()
        return tok.kind == "op" and tok.value == op

    def match_op(self, op: str) -> bool:
        if self.at_op(op):
            self.advance()
            return True
        return False

    def expect_op(self, op: str) -> Token:
        if not self.at_op(op):
            self.error("expected %r" % op)
        return self.advance()

    def error(self, message: str) -> None:
        tok = self.peek()
        if tok.kind == "eof":
            raise QueryError("syntax error: %s at end of query" % message)
        raise QueryError(
            "syntax error: %s at position %d near %r"
            % (message, tok.start, tok.text)
        )

    # -- grammar ------------------------------------------------------------

    def parse(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.match_kw("DISTINCT")
        items = self.parse_select_items()
        self.expect_kw("FROM")
        table = self.parse_name()

        where = None
        if self.match_kw("WHERE"):
            where = self.parse_expr()

        group_by: List[Expr] = []
        if self.match_kw("GROUP"):
            self.expect_kw("BY")
            group_by.append(self.parse_expr())
            while self.match_op(","):
                group_by.append(self.parse_expr())

        having = None
        if self.match_kw("HAVING"):
            having = self.parse_expr()

        order_by: List[OrderItem] = []
        if self.match_kw("ORDER"):
            self.expect_kw("BY")
            order_by.append(self.parse_order_item())
            while self.match_op(","):
                order_by.append(self.parse_order_item())

        limit = None
        offset = None
        if self.match_kw("LIMIT"):
            limit = self.parse_integer()
            if self.match_kw("OFFSET"):
                offset = self.parse_integer()

        self.match_op(";")
        if self.peek().kind != "eof":
            self.error("unexpected token")

        return Query(
            sql=self.sql,
            distinct=distinct,
            items=items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def parse_select_items(self) -> List[SelectItem]:
        if self.at_op("*"):
            self.advance()
            return [SelectItem(expr=None, alias=None, star=True)]

        items = [self.parse_select_item()]
        while self.match_op(","):
            items.append(self.parse_select_item())
        return items

    def parse_select_item(self) -> SelectItem:
        expr = self.parse_expr()
        alias = None
        if self.match_kw("AS"):
            alias = self.parse_name()
        elif self.peek().kind in ("name", "qname"):
            alias = self.parse_name()
        return SelectItem(expr=expr, alias=alias)

    def parse_order_item(self) -> OrderItem:
        expr = self.parse_expr()
        descending = False
        if self.match_kw("ASC"):
            descending = False
        elif self.match_kw("DESC"):
            descending = True
        return OrderItem(expr=expr, descending=descending)

    def parse_integer(self) -> int:
        tok = self.peek()
        if tok.kind != "number" or not isinstance(tok.value, int):
            self.error("expected an integer")
        self.advance()
        return tok.value

    def parse_name(self) -> str:
        tok = self.peek()
        if tok.kind not in ("name", "qname"):
            self.error("expected a name")
        self.advance()
        return tok.value

    # -- expressions --------------------------------------------------------

    def parse_expr(self) -> Expr:
        return self.parse_or()

    def parse_or(self) -> Expr:
        left = self.parse_and()
        while self.at_kw("OR"):
            self.advance()
            right = self.parse_and()
            left = Binary(
                start=left.start, end=right.end, op="OR", left=left, right=right
            )
        return left

    def parse_and(self) -> Expr:
        left = self.parse_not()
        while self.at_kw("AND"):
            self.advance()
            right = self.parse_not()
            left = Binary(
                start=left.start, end=right.end, op="AND", left=left, right=right
            )
        return left

    def parse_not(self) -> Expr:
        if self.at_kw("NOT"):
            tok = self.advance()
            operand = self.parse_not()
            return Unary(
                start=tok.start, end=operand.end, op="NOT", operand=operand
            )
        return self.parse_comparison()

    def parse_comparison(self) -> Expr:
        left = self.parse_additive()

        if self.at_kw("IS"):
            self.advance()
            negated = self.match_kw("NOT")
            null_tok = self.expect_kw("NULL")
            return IsNull(
                start=left.start,
                end=null_tok.end,
                operand=left,
                negated=negated,
            )

        negated = False
        if self.at_kw("NOT"):
            nxt = self.peek(1)
            if nxt.kind == "kw" and nxt.value in ("IN", "BETWEEN", "LIKE"):
                self.advance()
                negated = True

        if self.match_kw("IN"):
            self.expect_op("(")
            items = [self.parse_expr()]
            while self.match_op(","):
                items.append(self.parse_expr())
            close = self.expect_op(")")
            return InList(
                start=left.start,
                end=close.end,
                operand=left,
                items=items,
                negated=negated,
            )

        if self.match_kw("BETWEEN"):
            low = self.parse_additive()
            self.expect_kw("AND")
            high = self.parse_additive()
            return Between(
                start=left.start,
                end=high.end,
                operand=left,
                low=low,
                high=high,
                negated=negated,
            )

        if self.match_kw("LIKE"):
            pattern = self.parse_additive()
            return Like(
                start=left.start,
                end=pattern.end,
                operand=left,
                pattern=pattern,
                negated=negated,
            )

        tok = self.peek()
        if tok.kind == "op" and tok.value in _COMPARISON_OPS:
            self.advance()
            right = self.parse_additive()
            op = "!=" if tok.value == "<>" else tok.value
            return Binary(
                start=left.start, end=right.end, op=op, left=left, right=right
            )

        return left

    def parse_additive(self) -> Expr:
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok.kind == "op" and tok.value in ("+", "-", "||"):
                self.advance()
                right = self.parse_multiplicative()
                left = Binary(
                    start=left.start, end=right.end, op=tok.value, left=left, right=right
                )
            else:
                return left

    def parse_multiplicative(self) -> Expr:
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok.kind == "op" and tok.value in ("*", "/"):
                self.advance()
                right = self.parse_unary()
                left = Binary(
                    start=left.start, end=right.end, op=tok.value, left=left, right=right
                )
            else:
                return left

    def parse_unary(self) -> Expr:
        if self.at_op("-"):
            tok = self.advance()
            operand = self.parse_unary()
            return Unary(
                start=tok.start, end=operand.end, op="-", operand=operand
            )
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        tok = self.peek()

        if tok.kind == "number":
            self.advance()
            return Literal(start=tok.start, end=tok.end, value=tok.value)

        if tok.kind == "string":
            self.advance()
            return Literal(start=tok.start, end=tok.end, value=tok.value)

        if tok.kind == "kw":
            if tok.value == "NULL":
                self.advance()
                return Literal(start=tok.start, end=tok.end, value=None)
            if tok.value == "TRUE":
                self.advance()
                return Literal(start=tok.start, end=tok.end, value=True)
            if tok.value == "FALSE":
                self.advance()
                return Literal(start=tok.start, end=tok.end, value=False)
            self.error("expected an expression")

        if tok.kind in ("name", "qname"):
            self.advance()
            if self.at_op("("):
                return self.parse_call(tok)
            return Column(
                start=tok.start,
                end=tok.end,
                name=tok.value,
                quoted=(tok.kind == "qname"),
            )

        if tok.kind == "op" and tok.value == "(":
            open_tok = self.advance()
            inner = self.parse_expr()
            close_tok = self.expect_op(")")
            return Paren(start=open_tok.start, end=close_tok.end, operand=inner)

        self.error("expected an expression")
        raise AssertionError("unreachable")

    def parse_call(self, name_tok: Token) -> Call:
        self.expect_op("(")

        if self.at_op("*"):
            self.advance()
            close = self.expect_op(")")
            return Call(
                start=name_tok.start,
                end=close.end,
                name=name_tok.value,
                args=[],
                star=True,
            )

        args: List[Expr] = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.match_op(","):
                args.append(self.parse_expr())
        close = self.expect_op(")")
        return Call(
            start=name_tok.start,
            end=close.end,
            name=name_tok.value,
            args=args,
            star=False,
        )


def parse(sql: str) -> Query:
    return Parser(sql).parse()

