"""Tests for minisql. Run with ``python -m unittest discover``."""

import contextlib
import io
import os
import tempfile
import unittest

import minisql
from minisql.__main__ import main as cli_main


PRODUCTS = """id,name,category,price
1,widget,tools,25
2,gadget,toys,12.5
3,doohickey,tools,7
"""

EXTRA = """a,b,c
1,2.5,hello
,3.,it's
-4,.5,
"""

PRICES = """id,"unit price"
1,10
2,
"""


class MiniSqlTest(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.dir = self._tmp.name
        self.write("products.csv", PRODUCTS)
        self.write("extra.csv", EXTRA)
        self.write("prices.csv", PRICES)

    def tearDown(self):
        self._tmp.cleanup()

    def write(self, name, text):
        with open(os.path.join(self.dir, name), "w", encoding="utf-8") as fh:
            fh.write(text)

    def q(self, sql):
        return minisql.run(sql, self.dir)

    def rows(self, sql):
        return self.q(sql).rows

    def assertQueryError(self, sql):
        with self.assertRaises(minisql.QueryError):
            self.q(sql)

    # -- basics ---------------------------------------------------------

    def test_spec_example(self):
        result = self.q(
            "SELECT name, price FROM products WHERE price > 10 "
            "ORDER BY price DESC"
        )
        self.assertEqual(result.columns, ["name", "price"])
        self.assertEqual(result.rows, [("widget", 25), ("gadget", 12.5)])

    def test_csv_conversion(self):
        result = self.q("SELECT a, b, c FROM extra")
        self.assertEqual(result.columns, ["a", "b", "c"])
        self.assertEqual(
            result.rows,
            [
                (1, 2.5, "hello"),
                (None, 3.0, "it's"),
                (-4, 0.5, None),
            ],
        )

    def test_select_star(self):
        result = self.q("SELECT * FROM products")
        self.assertEqual(
            result.columns, ["id", "name", "category", "price"]
        )
        self.assertEqual(len(result.rows), 3)

    def test_case_insensitive_columns_and_keywords(self):
        self.assertEqual(
            self.rows("select NAME from products where PRICE > 20"),
            [("widget",)],
        )

    def test_missing_table_and_column(self):
        self.assertQueryError("SELECT * FROM nope")
        self.assertQueryError("SELECT nope FROM products")

    def test_quoted_names(self):
        result = self.q('SELECT "unit price" FROM prices')
        self.assertEqual(result.columns, ["unit price"])
        self.assertEqual(result.rows, [(10,), (None,)])

    def test_string_escapes(self):
        self.assertEqual(self.rows("SELECT 'it''s' FROM products LIMIT 1"),
                         [("it's",)])

    def test_aliases(self):
        result = self.q("SELECT name, price AS cost FROM products LIMIT 1")
        self.assertEqual(result.columns, ["name", "cost"])
        result = self.q("SELECT name n FROM products LIMIT 1")
        self.assertEqual(result.columns, ["name", "n"])

    def test_default_output_names(self):
        result = self.q("SELECT price * 2 FROM products LIMIT 1")
        self.assertEqual(result.columns, ["price * 2"])
