input.content:
import os
import random
import tempfile

import minisql

with tempfile.TemporaryDirectory() as d:
    with open(os.path.join(d, "t.csv"), "w") as f:
        f.write("a,b,s\n1,2.5,x\n,3,y\n-4,,z\n1,2.5,x\n")

    exprs = [
        "a", "b", "s", "*", "1", "2.5", "'x'", "NULL", "TRUE", "FALSE",
        "-a", "a + b", "a - b", "a * b", "a / b", "a || s", "s || a",
        "a = b", "a != b", "a < b", "a <= b", "a > b", "a >= b",
        "a IS NULL", "a IS NOT NULL", "a IN (1, 2, NULL)",
        "a NOT IN (1, NULL)", "a BETWEEN 1 AND 3", "a NOT BETWEEN 1 AND 3",
        "s LIKE 'x%'", "s NOT LIKE '%z'", "NOT a = 1", "a = 1 AND b = 2",
        "a = 1 OR b = 2", "LOWER(s)", "UPPER(s)", "LENGTH(s)", "ABS(a)",
        "ROUND(b)", "ROUND(b, 1)", "COALESCE(a, b, 0)",
        "COUNT(*)", "COUNT(a)", "SUM(a)", "AVG(b)", "MIN(s)", "MAX(s)",
        "COUNT(*) + 1", "ROUND(AVG(b), 1)", "COALESCE(SUM(a), 0)",
    ]

    queries = []
    for _ in range(3000):
        select = ", ".join(random.choice(exprs) for _ in range(random.randint(1, 3)))
        parts = ["SELECT", select, "FROM t"]
        if random.random() < 0.5:
            parts += ["WHERE", random.choice(exprs)]
        if random.random() < 0.4:
            parts += ["GROUP BY", random.choice(exprs)]
        if random.random() < 0.3:
            parts += ["HAVING", random.choice(exprs)]
        if random.random() < 0.5:
            order = random.choice(exprs)
            if random.random() < 0.3:
                order += " DESC"
            parts += ["ORDER BY", order]
        if random.random() < 0.3:
            parts += ["LIMIT", str(random.randint(0, 5))]
            if random.random() < 0.4:
                parts += ["OFFSET", str(random.randint(0, 3))]
        queries.append(" ".join(parts))

    failures = []
    for sql in queries:
        try:
            minisql.run(sql, d)
        except minisql.QueryError:
            pass
        except Exception as exc:
            failures.append((sql, type(exc).__name__, str(exc)))

    if failures:
        for item in failures[:20]:
            print(item)
        print("FAILURES:", len(failures))
    else:
        print("no non-QueryError failures")

